type NavItemProps = {
  className?: string
  icon?: React.ReactNode | null
  state?: "Active" | "Default"
}

function NavItem({ className, icon = null, state = "Active" }: NavItemProps) {
  const isDefault = state === "Default"
  return (
    <div
      className={
        className ||
        `h-[54px] relative rounded-[16px] w-[180px] ${
          isDefault
            ? ""
            : "bg-[#ef5a27] drop-shadow-[0px_1px_1px_rgba(0,0,0,0.05)]"
        }`
      }
    >
      <div className="flex flex-row items-center size-full">
        <div className="content-stretch flex gap-[10px] items-center px-[13px] relative size-full">
          <div
            className={`bg-white content-stretch flex items-center justify-center relative rounded-[12px] shrink-0 size-[30px] ${
              isDefault ? "drop-shadow-[0px_1px_1px_rgba(0,0,0,0.05)]" : ""
            }`}
            data-name="icon-container"
          >
            {state === "Active" &&
              (icon || <NavIcon className="relative shrink-0 size-[15px]" />)}
            {isDefault &&
              (icon || (
                <div
                  className="relative shrink-0 size-[15px]"
                  data-name="Nav Icon"
                >
                  <div
                    className="absolute left-0 size-[15px] top-0"
                    data-name="dash"
                  >
                    <svg
                      className="absolute block inset-0 size-full"
                      fill="none"
                      height="15"
                      preserveAspectRatio="none"
                      viewBox="0 0 15 15"
                      width="15"
                    >
                      <g clipPath="url(#clip0_0_3344)" id="dash">
                        <path
                          d={svgPaths.p37964b40}
                          fill="#8A9CB4"
                          id="Vector"
                        />
                      </g>
                      <defs>
                        <clipPath id="clip0_0_3344">
                          <rect fill="white" height="15" width="15" />
                        </clipPath>
                      </defs>
                    </svg>
                  </div>
                </div>
              ))}
          </div>
          <p
            className={`[word-break:break-word] leading-[22px] not-italic relative shrink-0 text-[14px] tracking-[0.01px] whitespace-nowrap ${
              isDefault
                ? 'font-["Pretendard:Regular",sans-serif] text-[#2a3461]'
                : 'font-["Pretendard:Medium",sans-serif] text-white'
            }`}
          >
            메뉴 이름
          </p>
        </div>
      </div>
    </div>
  )
}

